// Check each source for emails from the past 48 hours
const SOURCES = [
  { source: 'nik_sharma', author: 'Nik Sharma', query: 'from:niksharma@workweek.com newer_than:2d' },
  { source: 'taylor_holiday', author: 'Taylor Holiday / CTC', query: 'from:taylorholiday@commonthreadco.com newer_than:2d' },
  { source: 'matt_bertulli', author: 'Matt Bertulli', query: 'from:m@mattbertulli.com newer_than:2d' },
  { source: 'chase_dimond', author: 'Chase Dimond', query: '(from:chase@chasedimond.com OR from:ecomemailmarketer@mail.beehiiv.com) newer_than:2d' },
  { source: 'operators_newsletter', author: 'Operators Newsletter', query: 'from:news@operatorscontent.com newer_than:2d' },
];
return SOURCES.map(s => ({ json: s }));

const msg = $json;
const source = $('Source Config').first().json;

let bodyText = '';
let bodyHtml = '';

if (msg.payload) {
  const payload = msg.payload;
  if (payload.body && payload.body.data) {
    const decoded = Buffer.from(payload.body.data, 'base64').toString('utf-8');
    if (payload.mimeType === 'text/html') bodyHtml = decoded;
    else bodyText = decoded;
  }
  const parts = payload.parts || [];
  for (const part of parts) {
    if (part.body && part.body.data) {
      const decoded = Buffer.from(part.body.data, 'base64').toString('utf-8');
      if (part.mimeType === 'text/plain' && !bodyText) bodyText = decoded;
      if (part.mimeType === 'text/html' && !bodyHtml) bodyHtml = decoded;
    }
    const subparts = part.parts || [];
    for (const sp of subparts) {
      if (sp.body && sp.body.data) {
        const decoded = Buffer.from(sp.body.data, 'base64').toString('utf-8');
        if (sp.mimeType === 'text/plain' && !bodyText) bodyText = decoded;
        if (sp.mimeType === 'text/html' && !bodyHtml) bodyHtml = decoded;
      }
    }
  }
}

const headers = {};
const rawHeaders = (msg.payload && msg.payload.headers) || msg.headers || [];
for (const h of rawHeaders) {
  headers[h.name.toLowerCase()] = h.value;
}

return [{
  json: {
    email_id: msg.id || msg.messageId,
    source: source.source,
    author: source.author,
    subject: headers['subject'] || '',
    published_at: headers['date'] ? new Date(headers['date']).toISOString() : null,
    sender_email: headers['from'] || '',
    body_html: bodyHtml,
    body_text: bodyText,
  }
}];
